import json


def _quoted(ch):
    if ch == "'": return "\\'"
    if ch == '\\': return '\\\\'
    if ch == '\n': return '\\n'
    if ch == '\r': return '\\r'
    if ch == '\t': return '\\t'
    if ord(ch) < 32 or ord(ch) == 127: return '\\x%02x' % ord(ch)
    return ch


def diagnostic(text):
    """Return encoding/json-like syntax diagnostic, or None for valid JSON."""
    try:
        json.loads(text)
        return None
    except json.JSONDecodeError as e:
        p = e.pos
